{
    "name": "mufeedvh-website",
    "version": "1.0.0",
    "description": "HTML formatter for Zola-generated website",
    "type": "module",
    "scripts": {
        "format-html": "bun format-html.js",
        "build": "zola build && bun format-html.js"
    },
    "devDependencies": {
        "prettier": "^3.1.0",
        "shadcn": "^3.4.2"
    }
}

#!/usr/bin/env bun


import { promises as fs } from 'fs';
import path from 'path';
import prettier from 'prettier';

async function findWebFiles(dir) {
    const entries = await fs.readdir(dir, { withFileTypes: true });
    const files = await Promise.all(
        entries.map(async (entry) => {
            const fullPath = path.join(dir, entry.name);
            if (entry.isDirectory()) {
                return findWebFiles(fullPath);
            } else if (entry.name.endsWith('.html') || entry.name.endsWith('.css') || entry.name.endsWith('.js')) {
                return fullPath;
            }
            return null;
        })
    );

    return files.flat().filter(file => file !== null);
}

async function formatWebFile(filePath) {
    try {
        if (path.basename(filePath) === 'sitemap.xml') {
            return;
        }

        const content = await fs.readFile(filePath, 'utf-8');
        const ext = path.extname(filePath).toLowerCase();

        let config;
        switch (ext) {
            case '.html':
                config = {
                    parser: 'html',
                    printWidth: 120,
                    tabWidth: 4,
                    useTabs: false,
                    htmlWhitespaceSensitivity: 'css',
                    bracketSameLine: false,
                    singleAttributePerLine: false,
                    vueIndentScriptAndStyle: false,
                    embeddedLanguageFormatting: 'auto',
                    proseWrap: 'preserve'
                };
                break;
            case '.css':
                config = {
                    parser: 'css',
                    printWidth: 120,
                    tabWidth: 4,
                    useTabs: false,
                    singleQuote: false,
                    semi: true
                };
                break;
            case '.js':
                config = {
                    parser: 'babel',
                    printWidth: 120,
                    tabWidth: 4,
                    useTabs: false,
                    singleQuote: true,
                    semi: true,
                    trailingComma: 'es5',
                    bracketSpacing: true,
                    arrowParens: 'avoid'
                };
                break;
            default:
                console.log(`⚠️  Skipping unsupported file type: ${filePath}`);
                return;
        }

        const formatted = await prettier.format(content, config);

        await fs.writeFile(filePath, formatted, 'utf-8');
        console.log(`✅ Formatted: ${filePath}`);
    } catch (error) {
        console.error(`❌ Error formatting ${filePath}:`, error.message);
    }
}

async function main() {
    const publicDir = path.join(process.cwd(), 'public');

    try {
        await fs.access(publicDir);
    } catch {
        console.error('❌ Public directory not found. Make sure to run "zola build" first.');
        process.exit(1);
    }

    console.log('🔍 Finding web files (HTML, CSS, JS) in public directory...');
    const webFiles = await findWebFiles(publicDir);

    if (webFiles.length === 0) {
        console.log('⚠️  No web files found in public directory.');
        return;
    }

    console.log(`📝 Found ${webFiles.length} web files to format.`);

    await Promise.all(webFiles.map(formatWebFile));

    console.log('✨ Web file formatting complete!');
}

main().catch(error => {
    console.error('❌ Script failed:', error);
    process.exit(1);
});

/*
 * Code blocks: language label, copy button, and a fold for long listings.
 * Syntax colours come from Zola's server-side highlighter (highlight_theme
 * = "css"); the only client-side colouring is the MNM Lang candy palette,
 * which no highlighter knows about.
 */
(function () {
    'use strict';

    var COLLAPSE_AFTER = 24;
    var MNM_CLASSES = { B: 'mnm-blue', G: 'mnm-green', R: 'mnm-red', Y: 'mnm-yellow', O: 'mnm-orange', N: 'mnm-brown' };

    function languageOf(pre, code) {
        var lang = pre.getAttribute('data-lang');
        if (!lang && code) {
            var match = code.className.match(/language-([\w+#-]+)/);
            if (match) lang = match[1];
        }
        if (lang === 'text' || lang === 'txt' || lang === 'plain') return '';
        return lang || '';
    }

    function makeCopyButton(source) {
        var button = document.createElement('button');
        button.type = 'button';
        button.className = 'code-copy';
        button.textContent = 'copy';
        button.setAttribute('aria-label', 'Copy code to clipboard');

        function settle(text, done) {
            button.textContent = text;
            button.classList.toggle('is-done', done);
            setTimeout(function () {
                button.textContent = 'copy';
                button.classList.remove('is-done');
            }, 1600);
        }

        button.addEventListener('click', function () {
            if (!navigator.clipboard) return settle('unavailable', false);
            navigator.clipboard.writeText(source.textContent.replace(/\n$/, '')).then(
                function () { settle('copied', true); },
                function () { settle('failed', false); }
            );
        });
        return button;
    }

    function enhance(pre) {
        if (pre.closest('.mnm-widget') || pre.parentElement.classList.contains('code-block')) return;

        var code = pre.querySelector('code');
        var source = code || pre;

        var block = document.createElement('div');
        block.className = 'code-block';
        pre.parentNode.insertBefore(block, pre);
        block.appendChild(pre);

        var tools = document.createElement('div');
        tools.className = 'code-tools';
        var lang = languageOf(pre, code);
        if (lang) {
            var label = document.createElement('span');
            label.className = 'code-lang';
            label.textContent = lang;
            tools.appendChild(label);
        }
        tools.appendChild(makeCopyButton(source));
        block.appendChild(tools);

        var lines = source.textContent.replace(/\n$/, '').split('\n').length;
        if (lines > COLLAPSE_AFTER) {
            block.classList.add('is-collapsed');
            var expand = document.createElement('button');
            expand.type = 'button';
            expand.className = 'code-expand';
            var expandLabel = 'show all ' + lines + ' lines';
            expand.textContent = expandLabel;
            expand.addEventListener('click', function () {
                var collapsed = block.classList.toggle('is-collapsed');
                expand.textContent = collapsed ? expandLabel : 'collapse';
                if (collapsed) block.scrollIntoView({ block: 'nearest' });
            });
            block.appendChild(expand);
        }
    }

    function colourMnm(code) {
        if (code.classList.contains('mnm-highlighted')) return;
        var html = '';
        var text = code.textContent;
        for (var i = 0; i < text.length; i++) {
            var ch = text.charAt(i);
            var cls = MNM_CLASSES[ch];
            html += cls ? '<span class="' + cls + '">' + ch + '</span>' : ch === '<' ? '&lt;' : ch === '&' ? '&amp;' : ch;
        }
        code.innerHTML = html;
        code.classList.add('mnm-highlighted');
    }

    function init() {
        document.querySelectorAll('pre code.language-mnm, pre[data-lang="mnm"] > code').forEach(colourMnm);
        document.querySelectorAll('pre').forEach(enhance);
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();

/*
 * Bookshelf: each book turns toward the cursor.
 *
 * The pointer's position over a book's stage is normalised to [-1, 1] on
 * both axes. The side under the cursor swings toward the viewer (left
 * reveals the spine, right the page edges, top the head, bottom the tail),
 * the book lifts off its plank, and a light sheen and floor shadow follow.
 * Values are eased toward their targets in a requestAnimationFrame loop that
 * stops when everything settles, so idle books cost nothing.
 *
 * Only runs for fine pointers that can hover, and never when the visitor
 * prefers reduced motion; the CSS rest pose already shows the book's depth.
 */
(function () {
    'use strict';

    var MAX_TURN = 50;      /* degrees about the vertical axis */
    var MAX_LEAN = 20;      /* degrees about the horizontal axis */
    var LIFT = 38;          /* px toward the viewer while hovered */
    var EASE = 0.14;        /* per-frame interpolation factor */

    var REST = { rx: 0, ry: 26, lift: 0, sx: 0.3, sy: 0.2, sheen: 0.3, shx: 0, shs: 1, sho: 0.7 };
    var PRESENTED = { rx: -6, ry: 34, lift: LIFT, sx: 0.4, sy: 0.3, sheen: 0.5, shx: -6, shs: 1.16, sho: 1 };

    var canHover = window.matchMedia('(hover: hover) and (pointer: fine)').matches;
    var reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if (!canHover || reduceMotion) return;

    function clamp(value) {
        return Math.min(1, Math.max(-1, value));
    }

    function animateBook(stage) {
        var book = stage.querySelector('.book-3d');
        if (!book) return;

        var current = Object.assign({}, REST);
        var target = Object.assign({}, REST);
        var frame = 0;

        function paint() {
            book.style.setProperty('--rx', current.rx.toFixed(2) + 'deg');
            book.style.setProperty('--ry', current.ry.toFixed(2) + 'deg');
            book.style.setProperty('--lift', current.lift.toFixed(2) + 'px');
            stage.style.setProperty('--mx', (current.sx * 100).toFixed(1) + '%');
            stage.style.setProperty('--my', (current.sy * 100).toFixed(1) + '%');
            stage.style.setProperty('--sheen', current.sheen.toFixed(3));
            stage.style.setProperty('--shx', current.shx.toFixed(2) + 'px');
            stage.style.setProperty('--shs', current.shs.toFixed(3));
            stage.style.setProperty('--sho', current.sho.toFixed(3));
        }

        function step() {
            var settled = true;
            for (var key in target) {
                var delta = target[key] - current[key];
                if (Math.abs(delta) < 0.005) {
                    current[key] = target[key];
                } else {
                    current[key] += delta * EASE;
                    settled = false;
                }
            }
            paint();
            frame = settled ? 0 : window.requestAnimationFrame(step);
            if (settled) book.classList.remove('is-live');
        }

        function nudge() {
            book.classList.add('is-live');
            if (!frame) frame = window.requestAnimationFrame(step);
        }

        function aimAt(clientX, clientY) {
            var rect = stage.getBoundingClientRect();
            if (!rect.width || !rect.height) return;
            var px = clamp(((clientX - rect.left) / rect.width) * 2 - 1);
            var py = clamp(((clientY - rect.top) / rect.height) * 2 - 1);
            target.ry = -px * MAX_TURN;
            target.rx = py * MAX_LEAN;
            target.lift = LIFT;
            target.sx = (px + 1) / 2;
            target.sy = (py + 1) / 2;
            target.sheen = 0.55;
            target.shx = -px * 12;
            target.shs = 1.18;
            target.sho = 1;
            nudge();
        }

        function rest() {
            Object.assign(target, REST);
            nudge();
        }

        stage.addEventListener('pointermove', function (event) {
            aimAt(event.clientX, event.clientY);
        });
        stage.addEventListener('pointerleave', rest);
        stage.addEventListener('focus', function () {
            Object.assign(target, PRESENTED);
            nudge();
        });
        stage.addEventListener('blur', rest);

        paint();
    }

    function init() {
        document.querySelectorAll('.book-stage').forEach(animateBook);
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();

/*
 * Small behaviours for posts: share/follow buttons, sidenote toggles on
 * narrow viewports, and the table of contents (built from the headings
 * inside `.prose`, with a light scroll spy).
 */
(function () {
    'use strict';

    /* ---- Share / follow (called from inline onclick in content) ---- */

    function flashLabel(button, text) {
        var label = button.querySelector('.btn-text') || button;
        if (!button.dataset.originalLabel) button.dataset.originalLabel = label.textContent;
        label.textContent = text;
        setTimeout(function () {
            label.textContent = button.dataset.originalLabel;
        }, 1800);
    }

    window.share_button = function () {
        var button = document.getElementById('share-button');
        var url = window.location.href;
        if (!navigator.clipboard) {
            if (button) flashLabel(button, 'Copy failed');
            return;
        }
        navigator.clipboard.writeText(url).then(
            function () { if (button) flashLabel(button, 'Link copied'); },
            function () { if (button) flashLabel(button, 'Copy failed'); }
        );
    };

    window.twitter_follow = function () {
        window.open('https://x.com/mufeedvh', '_blank', 'noopener');
    };

    /* ---- Sidenotes ---- */

    window.toggleSidenote = function (id) {
        var note = document.getElementById(id);
        if (note) note.classList.toggle('is-open');
    };

    document.addEventListener('click', function (event) {
        var marker = event.target.closest('.sidenote-marker');
        if (!marker) return;
        event.preventDefault();
        window.toggleSidenote(marker.dataset.sidenote);
    });

    /* ---- Table of contents ---- */

    function slugify(text) {
        return text
            .toLowerCase()
            .replace(/[^\w\s-]/g, '')
            .trim()
            .replace(/[\s_]+/g, '-')
            .replace(/-+/g, '-');
    }

    function buildToc(toc) {
        var list = toc.querySelector('.toc-list');
        var prose = document.querySelector('.prose');
        if (!list || !prose) return;

        var min = parseInt(toc.dataset.min, 10) || 2;
        var max = parseInt(toc.dataset.max, 10) || 4;

        var headings = Array.prototype.filter.call(
            prose.querySelectorAll('h1, h2, h3, h4, h5, h6'),
            function (heading) {
                var level = parseInt(heading.tagName.charAt(1), 10);
                if (level < min || level > max) return false;
                if (heading.closest('.mnm-widget, .button-wrapper, .toc, .fold')) return false;
                return heading.textContent.trim().length > 0;
            }
        );

        if (headings.length === 0) {
            toc.hidden = true;
            return;
        }

        headings.forEach(function (heading, index) {
            if (!heading.id) {
                var id = slugify(heading.textContent) || 'section-' + index;
                var candidate = id;
                var n = 2;
                while (document.getElementById(candidate)) candidate = id + '-' + n++;
                heading.id = candidate;
            }
            heading.classList.add('toc-anchor');
        });

        var stack = [{ level: null, list: list }];
        var links = [];

        headings.forEach(function (heading) {
            var level = parseInt(heading.tagName.charAt(1), 10);
            while (stack.length > 1 && level < stack[stack.length - 1].level) stack.pop();
            var top = stack[stack.length - 1];

            if (top.level === null) {
                top.level = level;
            } else if (level > top.level) {
                var lastItem = top.list.lastElementChild;
                if (lastItem) {
                    var nested = document.createElement('ol');
                    lastItem.appendChild(nested);
                    stack.push({ level: level, list: nested });
                    top = stack[stack.length - 1];
                } else {
                    top.level = level;
                }
            }

            var item = document.createElement('li');
            var link = document.createElement('a');
            link.href = '#' + heading.id;
            link.textContent = heading.textContent.trim();
            item.appendChild(link);
            top.list.appendChild(item);
            links.push({ link: link, heading: heading });
        });

        var ticking = false;
        function updateActive() {
            ticking = false;
            var threshold = window.scrollY + window.innerHeight * 0.25;
            var current = null;
            for (var i = links.length - 1; i >= 0; i--) {
                if (links[i].heading.offsetTop <= threshold) {
                    current = links[i];
                    break;
                }
            }
            links.forEach(function (entry) {
                entry.link.classList.toggle('is-active', entry === current);
            });
        }

        window.addEventListener('scroll', function () {
            if (!ticking) {
                ticking = true;
                window.requestAnimationFrame(updateActive);
            }
        }, { passive: true });
        updateActive();
    }

    function init() {
        document.querySelectorAll('details.toc').forEach(buildToc);
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();

(function() {
    var path = window.location.pathname.replace(/\/+$/, '') || '/';
    var isRabbitHole = path.startsWith('/rabbithole') || path.startsWith('/message');

    if (!isRabbitHole) return;

    var audio = document.createElement('audio');
    audio.src = '/assets/sounds/curious-alice.mp3';
    audio.loop = true;
    audio.volume = 0.4;
    audio.preload = 'auto';

    var savedTime = parseFloat(sessionStorage.getItem('rh-time')) || 0;
    var savedMuted = sessionStorage.getItem('rh-muted') === '1';

    audio.muted = savedMuted;

    function tryPlay() {
        var p = audio.play();
        if (p !== undefined) {
            p.catch(function() {
                function resume() {
                    audio.play();
                    document.removeEventListener('click', resume);
                    document.removeEventListener('keydown', resume);
                }
                document.addEventListener('click', resume);
                document.addEventListener('keydown', resume);
            });
        }
    }

    audio.addEventListener('loadedmetadata', function() {
        if (savedTime > 0 && savedTime < audio.duration) {
            audio.currentTime = savedTime;
        }
        tryPlay();
    }, { once: true });

    var lastSave = 0;
    audio.addEventListener('timeupdate', function() {
        var now = Date.now();
        if (now - lastSave > 500) {
            sessionStorage.setItem('rh-time', audio.currentTime);
            lastSave = now;
        }
    });

    window.addEventListener('beforeunload', function() {
        sessionStorage.setItem('rh-time', audio.currentTime);
        sessionStorage.setItem('rh-muted', audio.muted ? '1' : '0');
    });

    var btn = document.createElement('button');
    btn.className = 'rabbithole-mute-btn';

    var svgOn = '<svg class="mute-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">'
        + '<polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5"/>'
        + '<path d="M19.07 4.93a10 10 0 0 1 0 14.14"/>'
        + '<path d="M15.54 8.46a5 5 0 0 1 0 7.07"/>'
        + '</svg>';

    var svgOff = '<svg class="mute-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">'
        + '<polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5"/>'
        + '<line x1="23" y1="9" x2="17" y2="15"/>'
        + '<line x1="17" y1="9" x2="23" y2="15"/>'
        + '</svg>';

    function syncUI() {
        btn.innerHTML = audio.muted ? svgOff : svgOn;
        btn.setAttribute('aria-label', audio.muted ? 'Unmute audio' : 'Mute audio');
        btn.setAttribute('title', audio.muted ? 'Unmute audio' : 'Mute audio');
    }

    syncUI();

    btn.addEventListener('click', function(e) {
        e.stopPropagation();
        audio.muted = !audio.muted;
        sessionStorage.setItem('rh-muted', audio.muted ? '1' : '0');
        syncUI();
        if (!audio.muted) tryPlay();
    });

    document.body.appendChild(btn);
})();

